import{_ as n,l as o,o as e,c as l,v as t,p as s,x as i,d as p,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"显示原理","description":"","frontmatter":{"title":"显示原理","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/revelation-principle.md","filePath":"econ/revelation-principle.md","lastUpdated":1789023840000}'),d={name:"econ/revelation-principle.md"};function E(m,a,A,B,_,C){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="显示原理" tabindex="-1">显示原理 <a class="header-anchor" href="#显示原理" aria-label="Permalink to &quot;显示原理&quot;">​</a></h1><div class="epigraph"><p>任何通过博弈实施的激励相容结果，都可以由一个说真话的直接机制复制；设计者只需在直接机制上优化。</p><footer>—— Myerson, Incentive Compatibility and the Bargaining Problem, Econometrica, 1979；Gibbard, Econometrica, 1973；Dasgupta, Hammond and Maskin, RES, 1979</footer></div><p><a href="/econ/incomplete-contracts">上一课</a>（不完全合同）。在给定的合同形式里写 IC。缺口是：合同可以任意弯——先报价、再抽签、再谈判、再发信号。是否必须在这个大空间里搜？显示原理说不必。把「均衡里人们实际在做的」收成「把类型报给计划者，由计划者执行原均衡结果」，说真话本身是均衡。本课钉这一归约，信息课序结束；下一课程从 GDP 核算另起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>机制是一套博弈规则：消息空间 \\(M_i\\)，结果函数 \\(g(m)\\)。给定先验，BNE 或占优策略均衡给出结果映射 \\(\\theta\\mapsto x\\)。设计者关心的是这个映射（配置、支付），不是消息的名字。<a href="/econ/screening-rent">筛选菜单</a>、拍卖、公共品的林达尔表，都是某 \\(M\\) 上的机制。</p><p>直接机制：\\(M_i=\\Theta_i\\)，\\(g\\) 直接吃报告。显示原理：若某间接机制有一个均衡实施了映射 \\(x(\\theta)\\)，则存在直接机制，使说真话是均衡，且实施同一 \\(x(\\theta)\\)。证明是复制：计划者问类型，模拟各人在原机制均衡里会发的消息，再执行 \\(g\\)。偏离直接机制等于在原机制里发了均衡外消息，不会更好。</p><h3 id="显示不是「人人自动诚实」" tabindex="-1">显示不是「人人自动诚实」 <a class="header-anchor" href="#显示不是「人人自动诚实」" aria-label="Permalink to &quot;显示不是「人人自动诚实」&quot;">​</a></h3><p>原理不说真话是占优，也不说实施无成本。它说搜索可以限在直接、真话 IC 的机制类。真话 IC 仍可能很紧，信息租金、数量扭曲、不可能定理都还在。Gibbard–Satterthwaite 正是在直接机制上证明：非独裁的社会选择，在广泛定义域上无法占优策略实施。</p><p><span class="marginnote">贝叶斯显示原理用 BNE；占优策略显示原理更强，对应优势策略激励相容。拍卖里，Myerson 的最优拍卖在直接机制上对虚拟估值积分，不必枚举所有间接叫价规则。</span></p><p>原理假定设计者能承诺 \\(g\\)。若事后可以再谈，代理人会预见到被抽租，间接的分阶段机制可能严格优于一次显示。本课在承诺站住的基准里收束。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：不完全信息、准线性或一般偏好，共同先验（贝叶斯版）。结论：最优机制 = 在激励相容、可行、参与约束下选直接机制。委托–代理的「合同 \\(w(x)\\)」已经是直接的：代理人不报类型（道德风险无类型时），或报类型再配行动（混合模型）。有类型时，先用显示收成 \\(q(\\theta),t(\\theta)\\)，再优化——筛选课其实已经用了本课的结论。</p><p>公共品：林达尔价要真实 MRS，显示原理把「任意揭示博弈」收成「报 MRS」，但 IC 会挡住第一最佳（Green–Laffont 等），回到<a href="/econ/theory-of-second-best">次优</a>与租金。</p>',13)),(e(),s(h,null,{default:i(()=>[c(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20IND%5B%22%E4%BB%BB%E6%84%8F%E9%97%B4%E6%8E%A5%E6%9C%BA%E5%88%B6%20%2B%20%E5%9D%87%E8%A1%A1%22%5D%20--%3E%20DIR%5B%22%E7%9B%B4%E6%8E%A5%E6%9C%BA%E5%88%B6%EF%BC%9A%E6%8A%A5%20%CE%B8%22%5D%0A%20%20DIR%20--%3E%20TT%5B%22%E8%AF%B4%E7%9C%9F%E8%AF%9D%E6%98%AF%E5%9D%87%E8%A1%A1%22%5D%0A%20%20TT%20--%3E%20OPT%5B%22%E5%8F%AA%E5%9C%A8%20IC%20%E7%9B%B4%E6%8E%A5%E6%9C%BA%E5%88%B6%E4%B8%8A%E4%BC%98%E5%8C%96%22%5D%0A%20%20OPT%20--%3E%20STOP%5B%22%E4%BF%A1%E6%81%AF%E8%AF%BE%E5%BA%8F%E6%AD%A2%E4%BA%8E%E6%AD%A4%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>归约能成立，是因为计划者可以内部模拟均衡策略 \\(\\sigma_i(\\theta_i)\\)。代理人没有新的偏离空间：他能对计划者谎报的，不过是假装自己是另一类型，而这正是原均衡里「用另一类型的策略」已经比较过的。故 IC 不等式在直接机制上不多也不少。<a href="/econ/screening-rent">筛选</a>的菜单、<a href="/econ/principal-agent">委托–代理</a>的 \\(w(x)\\)，其实都已经是直接机制；本课只是把「为什么不必再搜更弯的规则」写成定理。</p><p>原理不创造信息。隐藏行动若发生在报告之后，仍要结果合同；显示只收「报告」这一层。动态、多次报告，有动态显示原理，承诺与重新谈判会破坏「一次报完」，本课不展开。信息课序到此工具收齐：BNE、PBE、隐藏类型、隐藏行动、IC 规划。下一课程从核算另起，不再把 GDP 当成某个机制的直接显示。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>显示原理要求设计者能承诺执行 \\(g\\)，不能事后改约。重新谈判、有限承诺，间接机制可能严格优于被显示过的直接机制。多重均衡时，「某一个均衡可显示」不保证所有均衡都说真话；实施理论要更强的条件（Maskin 单调等）。占优策略比贝叶斯更少机制可用。</p><p>也不要把显示原理写成宏观或公司金融的资本结构；那些后课程用别的摩擦。本课是博弈与信息主干的最后一课：工具收齐后，配置问题变成带 IC 的规划。</p><p>贝叶斯版用 BNE，占优策略版用优势策略 IC。后者更少机制，但执行不依赖先验是否被共同持有。</p><p>后课默认：谈机制设计，先写直接机制与真话 IC；再问承诺是否站得住。</p><h3 id="不可能性不被原理取消" tabindex="-1">不可能性不被原理取消 <a class="header-anchor" href="#不可能性不被原理取消" aria-label="Permalink to &quot;不可能性不被原理取消&quot;">​</a></h3><p>Gibbard–Satterthwaite 在广泛定义域上排除占优策略的非独裁社会选择。贝叶斯 IC 更宽，Myerson 最优拍卖走这一层：先把所有叫价规则收成 IC 的 \\(Q_i(\\theta),t_i(\\theta)\\)，再对虚拟估值优化。选哪一层 IC，是承诺与先验，不是显示原理能决定的。Myerson–Satterthwaite 同样：双边交易不能既有效又自愿又预算平衡；间接机制救不了直接机制做不到的事。柠檬关闭、竞争保险无均衡，都与可行 IC 配置集太小一致。</p><p>无承诺、合谋、事后谈判会让间接机制严格优于被显示过的直接机制。下一课程从 GDP 三种算法另起，不再把国民核算当成某个直接机制的真话显示。</p><p><span class="marginnote">筛选菜单、委托–代理的 \\(w(x)\\) 其实都已经是直接机制；本课只把「不必再搜更弯的规则」写成定理。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>间接机制的均衡结果可由说真话的直接机制复制。</li><li>设计者只在 IC 直接机制上优化；不消除租金与不可能。</li><li>需要承诺执行；重新谈判可打破归约。</li><li>信息课序在此收束，核算课序另起。</li><li>出处：Gibbard, 1973；Dasgupta–Hammond–Maskin, <em>RES</em> 1979；Myerson, <em>Econometrica</em> 1979。</li></ul>',14))])}const u=n(d,[["render",E]]);export{b as __pageData,u as default};
